insert into metodo.reto (id, texto, variante_corta, virtud, subcomponente, facultad, ambito, tipo, minutos_estimados, requiere_otra_persona, disparador, dif_colerico, dif_melancolico, dif_sanguineo, dif_flematico, obstaculo, repetible, pregunta_examen, fuente_libro, fuente_seccion, cita_literal, perfil_combinado, activo) values ('pru-01', 'Antes de tomar hoy una decisión que afecte a otros, pide la opinión de al menos una persona y escúchala hasta el final sin interrumpir.', 'Pide consejo antes de decidir', 'prudencia', 'deliberacion', 'razon', 'trabajo', 'accion', 10, true, 'reunion_donde_decido', 5, 2, 3, 2, 'autosatisfacción', true, '¿Pedí consejo antes de decidir? Si no, ¿fue por prisa (primera reacción) o porque decidí no hacerlo?', 'Del temperamento al carácter', '3. El colérico: su desafío personal', 'debe aprender a pedir consejo de forma habitual', null, true) on conflict (id) do update set texto = excluded.texto, variante_corta = excluded.variante_corta, virtud = excluded.virtud, subcomponente = excluded.subcomponente, facultad = excluded.facultad, ambito = excluded.ambito, tipo = excluded.tipo, minutos_estimados = excluded.minutos_estimados, requiere_otra_persona = excluded.requiere_otra_persona, disparador = excluded.disparador, dif_colerico = excluded.dif_colerico, dif_melancolico = excluded.dif_melancolico, dif_sanguineo = excluded.dif_sanguineo, dif_flematico = excluded.dif_flematico, obstaculo = excluded.obstaculo, repetible = excluded.repetible, pregunta_examen = excluded.pregunta_examen, fuente_libro = excluded.fuente_libro, fuente_seccion = excluded.fuente_seccion, cita_literal = excluded.cita_literal, perfil_combinado = excluded.perfil_combinado, activo = excluded.activo;
insert into metodo.reto (id, texto, variante_corta, virtud, subcomponente, facultad, ambito, tipo, minutos_estimados, requiere_otra_persona, disparador, dif_colerico, dif_melancolico, dif_sanguineo, dif_flematico, obstaculo, repetible, pregunta_examen, fuente_libro, fuente_seccion, cita_literal, perfil_combinado, activo) values ('pru-02', 'Hoy toma una decisión que llevas aplazando. Fija la hora, decide y comunícala, aunque no tengas toda la información.', 'Decide hoy lo aplazado', 'prudencia', 'decision', 'razon', 'trabajo', 'accion', 15, false, 'tarea_pendiente', 1, 5, 2, 5, 'perfeccionismo', true, '¿Decidí? Si no, ¿qué certeza estaba esperando y era razonable esperarla?', 'Del temperamento al carácter', '4. El melancólico: su desafío personal', 'El objetivo de la prudencia no es deliberar, sino decidir', null, true) on conflict (id) do update set texto = excluded.texto, variante_corta = excluded.variante_corta, virtud = excluded.virtud, subcomponente = excluded.subcomponente, facultad = excluded.facultad, ambito = excluded.ambito, tipo = excluded.tipo, minutos_estimados = excluded.minutos_estimados, requiere_otra_persona = excluded.requiere_otra_persona, disparador = excluded.disparador, dif_colerico = excluded.dif_colerico, dif_melancolico = excluded.dif_melancolico, dif_sanguineo = excluded.dif_sanguineo, dif_flematico = excluded.dif_flematico, obstaculo = excluded.obstaculo, repetible = excluded.repetible, pregunta_examen = excluded.pregunta_examen, fuente_libro = excluded.fuente_libro, fuente_seccion = excluded.fuente_seccion, cita_literal = excluded.cita_literal, perfil_combinado = excluded.perfil_combinado, activo = excluded.activo;
