insert into metodo.reto (id, texto, variante_corta, virtud, subcomponente, facultad, ambito, tipo, minutos_estimados, requiere_otra_persona, disparador, dif_colerico, dif_melancolico, dif_sanguineo, dif_flematico, obstaculo, repetible, pregunta_examen, fuente_libro, fuente_seccion, cita_literal, perfil_combinado, activo) values ('aud-01', 'Hoy propón en voz alta una idea que llevas tiempo guardando, en una reunión o a alguien con capacidad de decidir.', 'Di la idea que guardas', 'fortaleza', 'audacia', 'voluntad', 'trabajo', 'accion', 5, true, 'reunion_de_equipo', 1, 5, 2, 4, 'conformismo', false, '¿Dije mi idea? Si no, ¿qué temía exactamente?', 'Del temperamento al carácter', '7. Desarrollo de la audacia', 'Comparte con todo el mundo lo que tienes en tu interior', null, true) on conflict (id) do update set texto = excluded.texto, variante_corta = excluded.variante_corta, virtud = excluded.virtud, subcomponente = excluded.subcomponente, facultad = excluded.facultad, ambito = excluded.ambito, tipo = excluded.tipo, minutos_estimados = excluded.minutos_estimados, requiere_otra_persona = excluded.requiere_otra_persona, disparador = excluded.disparador, dif_colerico = excluded.dif_colerico, dif_melancolico = excluded.dif_melancolico, dif_sanguineo = excluded.dif_sanguineo, dif_flematico = excluded.dif_flematico, obstaculo = excluded.obstaculo, repetible = excluded.repetible, pregunta_examen = excluded.pregunta_examen, fuente_libro = excluded.fuente_libro, fuente_seccion = excluded.fuente_seccion, cita_literal = excluded.cita_literal, perfil_combinado = excluded.perfil_combinado, activo = excluded.activo;
insert into metodo.reto (id, texto, variante_corta, virtud, subcomponente, facultad, ambito, tipo, minutos_estimados, requiere_otra_persona, disparador, dif_colerico, dif_melancolico, dif_sanguineo, dif_flematico, obstaculo, repetible, pregunta_examen, fuente_libro, fuente_seccion, cita_literal, perfil_combinado, activo) values ('aud-02', 'Inicia hoy una conversación con alguien que no conoces o con quien hace tiempo que no hablas.', 'Habla con alguien nuevo', 'fortaleza', 'audacia', 'voluntad', 'amistad', 'accion', 10, true, 'sin_disparador', 1, 5, 1, 4, null, true, '¿Fui yo quien inició la conversación?', 'Del temperamento al carácter', '7. Desarrollo de la audacia', 'No te aísles. Ve al encuentro de la gente', null, true) on conflict (id) do update set texto = excluded.texto, variante_corta = excluded.variante_corta, virtud = excluded.virtud, subcomponente = excluded.subcomponente, facultad = excluded.facultad, ambito = excluded.ambito, tipo = excluded.tipo, minutos_estimados = excluded.minutos_estimados, requiere_otra_persona = excluded.requiere_otra_persona, disparador = excluded.disparador, dif_colerico = excluded.dif_colerico, dif_melancolico = excluded.dif_melancolico, dif_sanguineo = excluded.dif_sanguineo, dif_flematico = excluded.dif_flematico, obstaculo = excluded.obstaculo, repetible = excluded.repetible, pregunta_examen = excluded.pregunta_examen, fuente_libro = excluded.fuente_libro, fuente_seccion = excluded.fuente_seccion, cita_literal = excluded.cita_literal, perfil_combinado = excluded.perfil_combinado, activo = excluded.activo;
insert into metodo.reto (id, texto, variante_corta, virtud, subcomponente, facultad, ambito, tipo, minutos_estimados, requiere_otra_persona, disparador, dif_colerico, dif_melancolico, dif_sanguineo, dif_flematico, obstaculo, repetible, pregunta_examen, fuente_libro, fuente_seccion, cita_literal, perfil_combinado, activo) values ('aud-03', 'Toma hoy una decisión que implique un riesgo razonable en tu vida profesional y que venías evitando por miedo a equivocarte.', 'Asume un riesgo razonable', 'fortaleza', 'audacia', 'voluntad', 'trabajo', 'accion', 20, false, 'oportunidad_con_riesgo', 1, 5, 2, 5, 'perfeccionismo', false, '¿Asumí el riesgo? ¿Lo que me frenaba era prudencia o miedo a equivocarme?', 'Del temperamento al carácter', '6. El flemático: su desafío personal', 'Debe practicar la audacia, porque la esencia de la prudencia no es la deliberación, sino la decisión', null, true) on conflict (id) do update set texto = excluded.texto, variante_corta = excluded.variante_corta, virtud = excluded.virtud, subcomponente = excluded.subcomponente, facultad = excluded.facultad, ambito = excluded.ambito, tipo = excluded.tipo, minutos_estimados = excluded.minutos_estimados, requiere_otra_persona = excluded.requiere_otra_persona, disparador = excluded.disparador, dif_colerico = excluded.dif_colerico, dif_melancolico = excluded.dif_melancolico, dif_sanguineo = excluded.dif_sanguineo, dif_flematico = excluded.dif_flematico, obstaculo = excluded.obstaculo, repetible = excluded.repetible, pregunta_examen = excluded.pregunta_examen, fuente_libro = excluded.fuente_libro, fuente_seccion = excluded.fuente_seccion, cita_literal = excluded.cita_literal, perfil_combinado = excluded.perfil_combinado, activo = excluded.activo;
