insert into metodo.reto (id, texto, variante_corta, virtud, subcomponente, facultad, ambito, tipo, minutos_estimados, requiere_otra_persona, disparador, dif_colerico, dif_melancolico, dif_sanguineo, dif_flematico, obstaculo, repetible, pregunta_examen, fuente_libro, fuente_seccion, cita_literal, perfil_combinado, activo) values ('dom-08', 'Cuando hoy te invada la tristeza o la ansiedad, di en voz baja «esto no es tan grave como parece» y haz la siguiente tarea.', 'Nombra la ansiedad y sigue', 'dominio de sí', null, 'voluntad', 'vida interior', 'accion', 2, false, 'bajon_emocional', 2, 5, 3, 2, null, true, '¿Lo hice? ¿Pude seguir trabajando?', 'Del temperamento al carácter', '4. El melancólico: su desafío personal', 'El pesimismo y la ansiedad pueden vencerse por medio del realismo', null, true) on conflict (id) do update set texto = excluded.texto, variante_corta = excluded.variante_corta, virtud = excluded.virtud, subcomponente = excluded.subcomponente, facultad = excluded.facultad, ambito = excluded.ambito, tipo = excluded.tipo, minutos_estimados = excluded.minutos_estimados, requiere_otra_persona = excluded.requiere_otra_persona, disparador = excluded.disparador, dif_colerico = excluded.dif_colerico, dif_melancolico = excluded.dif_melancolico, dif_sanguineo = excluded.dif_sanguineo, dif_flematico = excluded.dif_flematico, obstaculo = excluded.obstaculo, repetible = excluded.repetible, pregunta_examen = excluded.pregunta_examen, fuente_libro = excluded.fuente_libro, fuente_seccion = excluded.fuente_seccion, cita_literal = excluded.cita_literal, perfil_combinado = excluded.perfil_combinado, activo = excluded.activo;
insert into metodo.reto (id, texto, variante_corta, virtud, subcomponente, facultad, ambito, tipo, minutos_estimados, requiere_otra_persona, disparador, dif_colerico, dif_melancolico, dif_sanguineo, dif_flematico, obstaculo, repetible, pregunta_examen, fuente_libro, fuente_seccion, cita_literal, perfil_combinado, activo) values ('dom-09', 'Hoy no critiques a nadie que no esté presente, ni siquiera en tu cabeza. Si lo haces, para y piensa algo bueno de esa persona.', 'Cero críticas al ausente', 'dominio de sí', null, 'voluntad', 'trabajo', 'omision', 1, false, 'sin_disparador', 3, 5, 3, 2, null, true, '¿Cuántas veces critiqué a un ausente, aunque fuera mentalmente?', 'Del temperamento al carácter', '4. El melancólico: su desafío personal', 'Tiene tendencia a criticar a sus colegas (aunque solo sea internamente)', null, true) on conflict (id) do update set texto = excluded.texto, variante_corta = excluded.variante_corta, virtud = excluded.virtud, subcomponente = excluded.subcomponente, facultad = excluded.facultad, ambito = excluded.ambito, tipo = excluded.tipo, minutos_estimados = excluded.minutos_estimados, requiere_otra_persona = excluded.requiere_otra_persona, disparador = excluded.disparador, dif_colerico = excluded.dif_colerico, dif_melancolico = excluded.dif_melancolico, dif_sanguineo = excluded.dif_sanguineo, dif_flematico = excluded.dif_flematico, obstaculo = excluded.obstaculo, repetible = excluded.repetible, pregunta_examen = excluded.pregunta_examen, fuente_libro = excluded.fuente_libro, fuente_seccion = excluded.fuente_seccion, cita_literal = excluded.cita_literal, perfil_combinado = excluded.perfil_combinado, activo = excluded.activo;
insert into metodo.reto (id, texto, variante_corta, virtud, subcomponente, facultad, ambito, tipo, minutos_estimados, requiere_otra_persona, disparador, dif_colerico, dif_melancolico, dif_sanguineo, dif_flematico, obstaculo, repetible, pregunta_examen, fuente_libro, fuente_seccion, cita_literal, perfil_combinado, activo) values ('dom-10', 'Perdona hoy una ofensa concreta que guardas y hazlo visible: un saludo, un mensaje, un gesto normal con esa persona.', 'Suelta una ofensa guardada', 'dominio de sí', null, 'voluntad', 'amistad', 'accion', 5, true, 'persona_con_rencor', 3, 5, 2, 2, null, false, '¿Hice el gesto? ¿Qué me costó más, la decisión o la ejecución?', 'Del temperamento al carácter', '4. El melancólico: su desafío personal', 'le cuesta olvidar las ofensas sufridas', null, true) on conflict (id) do update set texto = excluded.texto, variante_corta = excluded.variante_corta, virtud = excluded.virtud, subcomponente = excluded.subcomponente, facultad = excluded.facultad, ambito = excluded.ambito, tipo = excluded.tipo, minutos_estimados = excluded.minutos_estimados, requiere_otra_persona = excluded.requiere_otra_persona, disparador = excluded.disparador, dif_colerico = excluded.dif_colerico, dif_melancolico = excluded.dif_melancolico, dif_sanguineo = excluded.dif_sanguineo, dif_flematico = excluded.dif_flematico, obstaculo = excluded.obstaculo, repetible = excluded.repetible, pregunta_examen = excluded.pregunta_examen, fuente_libro = excluded.fuente_libro, fuente_seccion = excluded.fuente_seccion, cita_literal = excluded.cita_literal, perfil_combinado = excluded.perfil_combinado, activo = excluded.activo;
insert into metodo.reto (id, texto, variante_corta, virtud, subcomponente, facultad, ambito, tipo, minutos_estimados, requiere_otra_persona, disparador, dif_colerico, dif_melancolico, dif_sanguineo, dif_flematico, obstaculo, repetible, pregunta_examen, fuente_libro, fuente_seccion, cita_literal, perfil_combinado, activo) values ('dom-11', 'Agradece hoy en voz alta la ayuda de tres personas distintas, nombrando qué hicieron.', 'Agradece tres veces', 'dominio de sí', null, 'voluntad', 'trabajo', 'accion', 3, true, 'sin_disparador', 4, 3, 1, 2, null, true, '¿A quién agradecí y por qué concreto?', 'Liderazgo virtuoso', 'Capítulo 3: Gratitud frente a envidia', 'Dan las gracias y recompensan a las personas por sus esfuerzos', null, true) on conflict (id) do update set texto = excluded.texto, variante_corta = excluded.variante_corta, virtud = excluded.virtud, subcomponente = excluded.subcomponente, facultad = excluded.facultad, ambito = excluded.ambito, tipo = excluded.tipo, minutos_estimados = excluded.minutos_estimados, requiere_otra_persona = excluded.requiere_otra_persona, disparador = excluded.disparador, dif_colerico = excluded.dif_colerico, dif_melancolico = excluded.dif_melancolico, dif_sanguineo = excluded.dif_sanguineo, dif_flematico = excluded.dif_flematico, obstaculo = excluded.obstaculo, repetible = excluded.repetible, pregunta_examen = excluded.pregunta_examen, fuente_libro = excluded.fuente_libro, fuente_seccion = excluded.fuente_seccion, cita_literal = excluded.cita_literal, perfil_combinado = excluded.perfil_combinado, activo = excluded.activo;
insert into metodo.reto (id, texto, variante_corta, virtud, subcomponente, facultad, ambito, tipo, minutos_estimados, requiere_otra_persona, disparador, dif_colerico, dif_melancolico, dif_sanguineo, dif_flematico, obstaculo, repetible, pregunta_examen, fuente_libro, fuente_seccion, cita_literal, perfil_combinado, activo) values ('dom-12', 'Elige hoy una pasión noble que tienes dormida (una causa, un proyecto de servicio, un arte) y dedícale 20 minutos.', 'Despierta una pasión noble', 'dominio de sí', null, 'voluntad', 'cultura', 'accion', 20, false, 'sin_disparador', 1, 2, 2, 5, 'conformismo', true, '¿Le dediqué el tiempo? ¿Qué se despertó?', 'Del temperamento al carácter', '6. El flemático: su desafío personal', 'Debe estimular sus pasiones nobles', null, true) on conflict (id) do update set texto = excluded.texto, variante_corta = excluded.variante_corta, virtud = excluded.virtud, subcomponente = excluded.subcomponente, facultad = excluded.facultad, ambito = excluded.ambito, tipo = excluded.tipo, minutos_estimados = excluded.minutos_estimados, requiere_otra_persona = excluded.requiere_otra_persona, disparador = excluded.disparador, dif_colerico = excluded.dif_colerico, dif_melancolico = excluded.dif_melancolico, dif_sanguineo = excluded.dif_sanguineo, dif_flematico = excluded.dif_flematico, obstaculo = excluded.obstaculo, repetible = excluded.repetible, pregunta_examen = excluded.pregunta_examen, fuente_libro = excluded.fuente_libro, fuente_seccion = excluded.fuente_seccion, cita_literal = excluded.cita_literal, perfil_combinado = excluded.perfil_combinado, activo = excluded.activo;
