insert into metodo.reto (id, texto, variante_corta, virtud, subcomponente, facultad, ambito, tipo, minutos_estimados, requiere_otra_persona, disparador, dif_colerico, dif_melancolico, dif_sanguineo, dif_flematico, obstaculo, repetible, pregunta_examen, fuente_libro, fuente_seccion, cita_literal, perfil_combinado, activo) values ('jus-02', 'Dedica hoy a tu familia un tiempo fijo y protegido, sin trabajo ni móvil, aunque haya tareas pendientes.', 'Tiempo protegido para la familia', 'justicia', null, 'voluntad', 'familia', 'accion', 60, true, 'tarde_con_hijos', 5, 3, 2, 2, null, true, '¿Respeté el tiempo? ¿Cuántas veces pensé en el trabajo?', 'Creado para la grandeza', 'Pasos prácticos: Justicia', '¿Soy consciente de la diferencia entre el amor al trabajo y la adicción a éste?', null, true) on conflict (id) do update set texto = excluded.texto, variante_corta = excluded.variante_corta, virtud = excluded.virtud, subcomponente = excluded.subcomponente, facultad = excluded.facultad, ambito = excluded.ambito, tipo = excluded.tipo, minutos_estimados = excluded.minutos_estimados, requiere_otra_persona = excluded.requiere_otra_persona, disparador = excluded.disparador, dif_colerico = excluded.dif_colerico, dif_melancolico = excluded.dif_melancolico, dif_sanguineo = excluded.dif_sanguineo, dif_flematico = excluded.dif_flematico, obstaculo = excluded.obstaculo, repetible = excluded.repetible, pregunta_examen = excluded.pregunta_examen, fuente_libro = excluded.fuente_libro, fuente_seccion = excluded.fuente_seccion, cita_literal = excluded.cita_literal, perfil_combinado = excluded.perfil_combinado, activo = excluded.activo;
