insert into metodo.reto (id, texto, variante_corta, virtud, subcomponente, facultad, ambito, tipo, minutos_estimados, requiere_otra_persona, disparador, dif_colerico, dif_melancolico, dif_sanguineo, dif_flematico, obstaculo, repetible, pregunta_examen, fuente_libro, fuente_seccion, cita_literal, perfil_combinado, activo) values ('mag-06', 'Dedica hoy 20 minutos a imaginar sin límites cómo sería tu vida o tu trabajo dentro de diez años si cumplieras tu misión. Escríbelo.', 'Imagina a diez años', 'magnanimidad', null, 'corazon', 'vida interior', 'contemplacion', 20, false, 'sin_disparador', 3, 1, 3, 5, 'conformismo', false, '¿Lo escribí? ¿Me atreví a imaginar en grande?', 'Del temperamento al carácter', '7. Desarrolla la magnanimidad', 'Dedica tiempo a tu imaginación. Trabájala, enriquécela, llévala hasta el límite', null, true) on conflict (id) do update set texto = excluded.texto, variante_corta = excluded.variante_corta, virtud = excluded.virtud, subcomponente = excluded.subcomponente, facultad = excluded.facultad, ambito = excluded.ambito, tipo = excluded.tipo, minutos_estimados = excluded.minutos_estimados, requiere_otra_persona = excluded.requiere_otra_persona, disparador = excluded.disparador, dif_colerico = excluded.dif_colerico, dif_melancolico = excluded.dif_melancolico, dif_sanguineo = excluded.dif_sanguineo, dif_flematico = excluded.dif_flematico, obstaculo = excluded.obstaculo, repetible = excluded.repetible, pregunta_examen = excluded.pregunta_examen, fuente_libro = excluded.fuente_libro, fuente_seccion = excluded.fuente_seccion, cita_literal = excluded.cita_literal, perfil_combinado = excluded.perfil_combinado, activo = excluded.activo;
insert into metodo.reto (id, texto, variante_corta, virtud, subcomponente, facultad, ambito, tipo, minutos_estimados, requiere_otra_persona, disparador, dif_colerico, dif_melancolico, dif_sanguineo, dif_flematico, obstaculo, repetible, pregunta_examen, fuente_libro, fuente_seccion, cita_literal, perfil_combinado, activo) values ('mag-07', 'Hoy no te compares con nadie. Cada vez que lo hagas, sustituye la comparación por una pregunta: «¿qué puedo hacer yo con mi talento?».', 'Cero comparaciones hoy', 'magnanimidad', null, 'corazon', 'vida interior', 'omision', 1, false, 'sin_disparador', 3, 4, 4, 3, null, true, '¿Cuántas veces me comparé? ¿Logré sustituirlo?', 'Del temperamento al carácter', '7. Desarrolla la magnanimidad', 'No te compares con nadie', null, true) on conflict (id) do update set texto = excluded.texto, variante_corta = excluded.variante_corta, virtud = excluded.virtud, subcomponente = excluded.subcomponente, facultad = excluded.facultad, ambito = excluded.ambito, tipo = excluded.tipo, minutos_estimados = excluded.minutos_estimados, requiere_otra_persona = excluded.requiere_otra_persona, disparador = excluded.disparador, dif_colerico = excluded.dif_colerico, dif_melancolico = excluded.dif_melancolico, dif_sanguineo = excluded.dif_sanguineo, dif_flematico = excluded.dif_flematico, obstaculo = excluded.obstaculo, repetible = excluded.repetible, pregunta_examen = excluded.pregunta_examen, fuente_libro = excluded.fuente_libro, fuente_seccion = excluded.fuente_seccion, cita_literal = excluded.cita_literal, perfil_combinado = excluded.perfil_combinado, activo = excluded.activo;
