insert into metodo.reto (id, texto, variante_corta, virtud, subcomponente, facultad, ambito, tipo, minutos_estimados, requiere_otra_persona, disparador, dif_colerico, dif_melancolico, dif_sanguineo, dif_flematico, obstaculo, repetible, pregunta_examen, fuente_libro, fuente_seccion, cita_literal, perfil_combinado, activo) values ('hum-04', 'Hoy, en una tarea de alguien a tu cargo, no intervengas ni la hagas por él aunque veas que podrías hacerla mejor.', 'No hagas su trabajo', 'humildad', 'fraternal', 'corazon', 'trabajo', 'omision', 1, true, 'encuentro_con_colaborador', 5, 4, 2, 2, null, true, '¿Me contuve? ¿Qué me costó más?', 'Creado para la grandeza', 'Pasos prácticos: Humildad', '¿Evito la tentación de hacer el trabajo de mis subordinados en su lugar?', null, true) on conflict (id) do update set texto = excluded.texto, variante_corta = excluded.variante_corta, virtud = excluded.virtud, subcomponente = excluded.subcomponente, facultad = excluded.facultad, ambito = excluded.ambito, tipo = excluded.tipo, minutos_estimados = excluded.minutos_estimados, requiere_otra_persona = excluded.requiere_otra_persona, disparador = excluded.disparador, dif_colerico = excluded.dif_colerico, dif_melancolico = excluded.dif_melancolico, dif_sanguineo = excluded.dif_sanguineo, dif_flematico = excluded.dif_flematico, obstaculo = excluded.obstaculo, repetible = excluded.repetible, pregunta_examen = excluded.pregunta_examen, fuente_libro = excluded.fuente_libro, fuente_seccion = excluded.fuente_seccion, cita_literal = excluded.cita_literal, perfil_combinado = excluded.perfil_combinado, activo = excluded.activo;
