insert into metodo.reto (id, texto, variante_corta, virtud, subcomponente, facultad, ambito, tipo, minutos_estimados, requiere_otra_persona, disparador, dif_colerico, dif_melancolico, dif_sanguineo, dif_flematico, obstaculo, repetible, pregunta_examen, fuente_libro, fuente_seccion, cita_literal, perfil_combinado, activo) values ('hum-11', 'Recuerda hoy, al empezar, que tu energía y tus talentos no son mérito tuyo sino un don. Dilo en una frase de agradecimiento.', 'Tu fuerza es un don', 'humildad', 'fundamental', 'corazon', 'vida interior', 'contemplacion', 2, false, 'inicio_del_dia', 5, 2, 3, 3, null, true, '¿Lo hice? ¿Cambió algo en cómo traté a los demás?', 'Del temperamento al carácter', '3. El colérico: su desafío personal', 'debe comprender que su fuerza fisiológica no es resultado de un esfuerzo personal, sino un don', null, true) on conflict (id) do update set texto = excluded.texto, variante_corta = excluded.variante_corta, virtud = excluded.virtud, subcomponente = excluded.subcomponente, facultad = excluded.facultad, ambito = excluded.ambito, tipo = excluded.tipo, minutos_estimados = excluded.minutos_estimados, requiere_otra_persona = excluded.requiere_otra_persona, disparador = excluded.disparador, dif_colerico = excluded.dif_colerico, dif_melancolico = excluded.dif_melancolico, dif_sanguineo = excluded.dif_sanguineo, dif_flematico = excluded.dif_flematico, obstaculo = excluded.obstaculo, repetible = excluded.repetible, pregunta_examen = excluded.pregunta_examen, fuente_libro = excluded.fuente_libro, fuente_seccion = excluded.fuente_seccion, cita_literal = excluded.cita_literal, perfil_combinado = excluded.perfil_combinado, activo = excluded.activo;
